from pathlib import Path
from docx import Document
import csv,json,zipfile
P=Path('/workspace/development-documentation')
rows=[['Issue / observation','Revision documented','Evidence status / next check'],['A second phone or display did not show another player','Reviewed independent presence and shared player state','Development reports include failures and later confirmations;attach actual multi-device evidence'],['Small phone character and excessive empty space','Fuller map view;35% zoom;20% slower movement','User reported approval;compare real before/after screens'],['Drink option changes looked too similar','Requested clearer ingredient differences within approved style','Attach two actual ingredient states;do not invent a quantitative improvement'],['Fishing movement felt jerky','Movement smoothing and response refinements','Reports describe partial improvement;do not claim all network latency eliminated'],['Fishing felt too difficult','10% larger range;3.5s target interval;4%/s loss','User requested settings and later approved;new timed performance study not recorded'],['iPhone keys changed colour without sound','Audio activation/recovery changes','Device feedback confirmed sound after changes;no claim of universal compatibility'],['Piano controls too near exit / idle player occupied seat','Raised controls;on-map panel;8s idle release','Attach current implementation and recorded feedback'],['Wish preview showed full sentence','Shortened preview;kept full text on open note','Attach actual preview/full-note comparison'],['Final exhibition encounter duration','Intended join-and-one-activity route around two minutes','Timed route including matching remains to be recorded']]
with (P/'Testing-evidence-table.csv').open('w',encoding='utf-8-sig',newline='') as f:csv.writer(f).writerows(rows)
d=Document();d.add_heading('Testing evidence table — content aid',0);t=d.add_table(rows=1,cols=3);t.style='Light Shading Accent 1'
for c,v in zip(t.rows[0].cells,rows[0]):c.text=v
for row in rows[1:]:
 for c,v in zip(t.add_row().cells,row):c.text=v
d.save(P/'Testing-evidence-table.docx')
refs='''# References and media credits — working list\n\nThese entries identify supplied documents and technical sources. Apply the referencing style in the unit outline;do not assume this working list already meets that style. Author/year information has not been supplied for the course files. Cite the relevant figure and paragraph on the page as well as listing the source here.\n\n- GRDE2053 Social Interactive Experiences. (n.d.). A2_Brief [Supplied assignment brief], pp.2–5. The file heading says Assignment One;the associated assessment rubric labels the exhibition A2.\n- GRDE2053 Social Interactive Experiences. (n.d.). SIE–DCI A2: Exhibition showcase [Supplied assessment rubric].\n- GRDE2053 Social Interactive Experiences. (n.d.). Session 2: Designing Participation [Supplied lecture slides], pp.6,8,10.\n- GRDE2053 Social Interactive Experiences. (n.d.). Session 3: Designing with Care [Supplied lecture slides], p.8 and Ethics & Inclusion discussion.\n- GRDE2053 Social Interactive Experiences. (n.d.). Session 5: Designing Interactions [Supplied lecture slides], slides6–11.\n- Social Interactive. (n.d.). A Social Interactive Experience for Campus Connection [Supplied concept deck], slides2,5,7–8. Confirm author/date and whether this matches the formal A1 submission.\n- p5.js. Documentation. https://p5js.org/\n- Firebase. Realtime Database documentation. https://firebase.google.com/docs/database/\n- GitHub. GitHub Pages documentation. https://docs.github.com/en/pages\n- MDN Web Docs. Web Audio API. https://developer.mozilla.org/en-US/docs/Web/API/Web_Audio_API\n- Project source and development screens: https://github.com/itsangelia/public-map-project . Use exact file/commit/date when choosing evidence. Screens generated during controlled browser checks are prototype screenshots,not participant-study photographs.\n\n## Media details to complete\n\n- Map and three avatar assets: supplied for this project;original creators,sources and licences not yet established. Do not claim these were independently hand-drawn by the student.\n- Activity entrances and fish images: record each supplied/generated/refined asset separately. The original map and avatars are not automatically covered by an AI declaration.\n- AI tools: assistance included ChatGPT/Codex and image-generation/refinement workflows. Confirm exact tool details,dates and asset-specific steps from the actual record.\n- Keep identifying information/private messages out of screenshots unless consent is appropriate.\n\nNo claim is made that full media permission or tutor AI approval has already been verified.\n'''
(P/'References-and-media-working-list.md').write_text(refs)
(P/'READ-ME-ZH.md').write_text('''# 开发PDF正文内容稿\n\n本套是排版用的内容，不是已经完成配图和引用的提交PDF。按13页正文写，每页约150–180英文词，另外加封面和参考文献；教师上限为正文15页，不含封面与参考文献。\n\n## 文件\n- Development-content-EN.docx：可直接复制排版的英文正文，已按13个页面主题分页。\n- Development-content-EN-ZH.docx：同版英文＋中文理解＋配图建议＋图注，中文说明不放入英文成品。\n- Development-content-EN.md：纯文字备份。\n- Testing-evidence-table.docx / .csv：第10页可用的真实问题与证据状态。\n- References-and-media-working-list.md：引用和素材待补项，不是已经核实齐全的最终参考文献。\n\n## 排版\n建议每页用一个明确标题、正文和1–3张有信息量的图。小图需要让老师读清；不要用大量截图填满页面。图注解释变化，不仅写界面名称。未知的旧版本数值、测试日期和人数不要补写。\n\n正文保留了开发记录可以支持的改动，未声称正式用户研究、普遍稳定性、已证明改善归属感或已获得导师AI批准。第13页涉及授权/批准的未知状态，提交前应按真实情况更新。\n\n必须核对：概念稿是否与正式A1一致；真实前后截图与复测记录；素材原作者及许可；unit outline引用格式；导师允许的AI范围及真实声明。若截图显示的版本与文字不同，以最终实现和真实记录修正。\n\n本轮只编写文档内容，不修改正式地图。\n''')
# Sanity checks on content and deliverables.
m=json.loads((P/'page-content.json').read_text());assert len(m)==13 and m[0]['page']==1 and m[-1]['page']==13
for x in m:assert all(x[k] for k in ['en','zh','evidence','caption','source'])
with zipfile.ZipFile(P/'Development-writing-package.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in P.iterdir():
  if f.suffix in ['.docx','.md','.csv','.json']:z.write(f,f.name)
print('Content, evidence guide and source working list checked.')
